package br.com.tapeteskalke.service; import br.com.tapeteskalke.exception.AccessDeniedBusinessException; import br.com.tapeteskalke.repository.PermissaoRepository; import br.com.tapeteskalke.security.CurrentUser; import java.util.*; import org.springframework.stereotype.Service;
@Service public class PermissionService { private final CurrentUser current; private final PermissaoRepository permissions; public static final List<String> PAGES=List.of("dashboard","clientes","funcionarios","produtos","vendas","compras","fornecedores","producao","entregas","relatorios","configuracoes"); public static final List<String> ACTIONS=List.of("clientes_criar","clientes_editar","clientes_excluir","produtos_criar","produtos_editar","produtos_excluir","vendas_criar","vendas_cancelar","compras_criar","compras_cancelar","producao_criar","producao_finalizar","producao_cancelar","despesas_criar","estoque_ajustar","entregas_criar","entregas_atualizar_status","funcionarios_criar","funcionarios_editar","funcionarios_excluir","relatorios_visualizar","configuracoes_editar"); public PermissionService(CurrentUser current,PermissaoRepository permissions){this.current=current;this.permissions=permissions;} public void action(String action){var u=current.require();if(!permissions.hasAction(u.role(),action))throw new AccessDeniedBusinessException("Sem permissão para: "+action);} public void page(String page){var u=current.require();if(!permissions.hasPage(u.role(),page))throw new AccessDeniedBusinessException("Sem acesso à página: "+page);} public Map<String,Boolean> pages(){return pagesFor(current.require().role());} public Map<String,Boolean> actions(){return actionsFor(current.require().role());} public Map<String,Boolean> pagesFor(String role){var r=new LinkedHashMap<String,Boolean>();for(var p:PAGES)r.put(p,permissions.hasPage(role,p));return r;} public Map<String,Boolean> actionsFor(String role){var r=new LinkedHashMap<String,Boolean>();for(var a:ACTIONS)r.put(a,permissions.hasAction(role,a));return r;} }